package jp.terada.midnitelogger;
import java.io.*; import java.net.*;
public class Modbus {public interface L{void log(String l,String m);} private final L l; private int tx=1; public Modbus(L x){l=x;}
 public int[] read(String host,int port,int unit,int addr,int count)throws IOException{Socket s=new Socket();l.log("INFO","TCP接続開始 "+host+":"+port);s.connect(new InetSocketAddress(host,port),5000);s.setSoTimeout(5000);l.log("OK","TCP接続成功");DataOutputStream o=new DataOutputStream(s.getOutputStream());ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream q=new DataOutputStream(b);int t=tx++&0xffff;q.writeShort(t);q.writeShort(0);q.writeShort(6);q.writeByte(unit);q.writeByte(3);q.writeShort(addr);q.writeShort(count);byte[] req=b.toByteArray();l.log("SEND","FC=3 Addr="+addr+" Count="+count);o.write(req);o.flush();DataInputStream in=new DataInputStream(s.getInputStream());byte[] h=new byte[7];in.readFully(h);int len=((h[4]&255)<<8)|(h[5]&255);byte[] p=new byte[len-1];in.readFully(p);s.close();int fc=p[0]&255;if((fc&128)!=0)throw new IOException("Modbus exception="+(p[1]&255)+" FC="+fc);if(fc!=3)throw new IOException("Unexpected FC="+fc);int bc=p[1]&255;if(bc!=count*2)throw new IOException("Byte count="+bc);int[] out=new int[count];for(int i=0;i<count;i++)out[i]=((p[2+i*2]&255)<<8)|(p[3+i*2]&255);l.log("RECV","Modbus応答 "+count+" registers");return out;}
}
